import { line } from 'axylo';

// A plain decimal string, as Axylo's own `parse: 'number'` accepts: '1438.75', '-1.5', '1e3'.
const DECIMAL = /^-?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?$/;

/**
 * The revenue field arrives as a mix of numbers and decimal strings. Axylo rejects every string
 * in a field that also holds numbers (AX106), and `parse: 'number'` only applies to a field that is
 * all strings, so convert here. Anything that is not a plain decimal string is passed through
 * unchanged, so Axylo still reports it instead of it being silently guessed at.
 */
function toNumber(value) {
  return typeof value === 'string' && DECIMAL.test(value) ? Number(value) : value;
}

/**
 * Draws the store's daily revenue as a line chart.
 * @param {HTMLElement} element the chart container
 * @param {ReadonlyArray<{ day: string, revenue: number | string | null }>} data rows from data.json
 * @returns the Axylo chart handle
 */
export default function render(element, data) {
  // New row objects: the caller's rows are never changed.
  const rows = data.map((row) => ({ ...row, revenue: toNumber(row.revenue) }));

  return line(element, {
    title: 'Daily store revenue',
    data: rows,
    // Each day is sent as a UTC midnight: read it as that calendar day, the same in every time zone.
    x: { field: 'day', type: 'date' },
    y: {
      field: 'revenue',
      label: 'Revenue',
      format: { minimumFractionDigits: 2, maximumFractionDigits: 2 },
    },
  });
}

