input.command:
node --input-type=module -e "
import { validate } from 'axylo';
import { readFileSync } from 'node:fs';
const data = JSON.parse(readFileSync('data.json', 'utf8'));
const DECIMAL = /^-?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?\$/;
const rows = data.map(r => ({ ...r, revenue: typeof r.revenue === 'string' && DECIMAL.test(r.revenue) ? Number(r.revenue) : r.revenue }));
const opts = d => ({ title: 'Daily store revenue', data: d, x: { field: 'day', type: 'date' },
  y: { field: 'revenue', label: 'Revenue', format: { minimumFractionDigits: 2, maximumFractionDigits: 2 } } });
for (const [name, d] of [['raw', data], ['converted', rows]]) {
  console.log('--', name);
  for (const p of validate('line', opts(d))) console.log(p.level, p.code, p.message);
}
console.log('caller rows unchanged:', JSON.stringify(data) === readFileSync('data.json','utf8').replace(/\s/g,'').length ? '' : JSON.stringify(data.map(r=>typeof r.revenue)));
console.log(rows.map(r => r.day.slice(0,10) + ' ' + r.revenue + ' ' + typeof r.revenue).join('\n'));
"

